package net.civeira.phylax.features.oauth.client.domain;

import java.util.Map;

import lombok.Builder;
import lombok.Getter;

/**
 * Keys, algorithms and flags a client may register through DCR besides the RFC 7591 core (OIDC
 * Registration §2, RFC 9449 §5.2, RFC 9126 §6; task V.3).
 *
 * <p>
 * Every value maps to a column the runtime already reads through {@code OauthClientPolicy}; a null
 * value or false means not registered. {@link DcrMetadataPolicy} validates them against the
 * algorithms the server announces.
 */
@Builder(toBuilder = true)
@Getter
public class DcrExtensionMetadata {

  /**
   * Nothing registered.
   */
  public static final DcrExtensionMetadata NONE = builder().build();

  /**
   * Inline public JWKS ({@code jwks}), as a JSON object with {@code keys}.
   */
  private final Map<String, Object> jwks;
  private final String jwksUri;
  private final String tokenEndpointAuthSigningAlg;
  private final String requestObjectSigningAlg;
  private final String idTokenSignedResponseAlg;
  private final String idTokenEncryptedResponseAlg;
  private final String idTokenEncryptedResponseEnc;
  private final String userinfoSignedResponseAlg;
  private final String userinfoEncryptedResponseAlg;
  private final String userinfoEncryptedResponseEnc;
  private final String authorizationSignedResponseAlg;
  /**
   * {@code public} or {@code pairwise}; null in a request means {@code public}.
   */
  private final String subjectType;
  /**
   * Only read to reject it: the server does not fetch nor verify sector documents.
   */
  private final String sectorIdentifierUri;
  private final boolean backchannelLogoutSessionRequired;
  private final boolean frontchannelLogoutSessionRequired;
  private final boolean dpopBoundAccessTokens;
  private final boolean requirePushedAuthorizationRequests;
  /**
   * Only read to reject it: mTLS is postponed (task 4.1).
   */
  private final boolean tlsClientCertificateBoundAccessTokens;

  /**
   * Whether the client registered keys, inline or by reference.
   *
   * @return true with {@code jwks} or {@code jwks_uri}
   */
  public boolean hasKeys() {
    return jwks != null || jwksUri != null;
  }
}
